<?php

namespace App\Filament\Resources;

use App\Filament\Resources\AdminResource\Pages;
use App\Models\User;
use AtrioTeam\FilamentHelper\Enums\UserRole;
use AtrioTeam\FilamentHelper\Filament\Tables\Decorators\TableDecorator;
use BackedEnum;
use Filament\Forms\Components\CheckboxList;
use Filament\Forms\Components\TextInput;
use Filament\Resources\Resource;
use Filament\Schemas\Components\Section;
use Filament\Schemas\Schema;
use Filament\Tables;
use Filament\Tables\Table;
use Illuminate\Database\Eloquent\Builder;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Support\Facades\Auth;
use Illuminate\Support\Facades\Hash;
use Illuminate\Support\HtmlString;
use Spatie\Permission\Models\Role;

/*
 * Manage all admin users (not superadmin)
 * The admin role cannot be removed for a user because it is necessary to access the cms.
 * Access to this resource is managed here
 * and NOT via a dedicated policy.
 */
class AdminResource extends Resource
{
    protected static ?string $model = User::class;

    protected static ?string $slug = 'admins';

    protected static BackedEnum|string|null $navigationIcon = 'heroicon-o-users';

    //    protected static ?int $navigationSort = 9001;

    public static function getNavigationGroup(): ?string
    {
        return RoleResource::getNavigationGroup();
    }

    public static function getNavigationLabel(): string
    {
        return  'Utenti amministratori';
    }


    public static function getPluralModelLabel(): string
    {
        return self::getNavigationLabel();
    }

    /*
     * The singular label for the model.
     * It is used as title in the "Edit" page.
     */
    public static function getModelLabel(): string
    {
        return 'Amministratore';
    }


    // Customize query to only retrieve users with the admin role.
    /**
     * @return Builder<User>
     */
    public static function getEloquentQuery(): Builder
    {
        // @phpstan-ignore method.notFound
        return static::getModel()::where('is_admin', true)->withoutRole(UserRole::SUPERADMIN);
    }

    public static function form(Schema $form): Schema
    {

        //        dd(array_column(UserRole::cases(), 'value'));
        return $form
            ->schema([
                //
                Section::make()->columnSpanFull()->columns(2)->schema([
                    TextInput::make('firstname')
                        ->label('Nome')
                        ->required(),
                    TextInput::make('lastname')
                        ->label('Cognome')
                        ->required(),
                    TextInput::make('email')
                        ->label('Email')
                        ->required()
                        ->email()
                        ->unique(ignoreRecord: true),

                ]),
                Section::make('Password')->columnSpanFull()->columns(2)->schema([
                    TextInput::make('password')
                        ->label('Password')
                        ->required()
                        ->password()
                        ->confirmed()
                        ->autocomplete('new-password')
                        ->dehydrateStateUsing(fn (string $state): string => Hash::make($state))
                        ->dehydrated(fn (?string $state): bool => filled($state))
                        ->required(fn (string $operation): bool => $operation === 'create'),
                TextInput::make('password_confirmation')
                        ->label('Conferma password')
                        ->password()
                        ->autocomplete('new-password'),
                ]),
                Section::make('Ruoli')->columnSpanFull()->columns(1)
                    ->description(new HtmlString('Per assegnare i permessi ai ruoli utilizzare Gestione permessi > Ruoli.'))
                    ->schema([

                        // role selector (many)
                        CheckboxList::make('roles')
                            ->hiddenLabel()
                            ->relationship(
                                titleAttribute: 'name',
                                modifyQueryUsing: fn (Builder $query) =>
                                    $query->with('permissions')->whereNot('name', UserRole::SUPERADMIN),
                            )
                    ]),
            ]);
    }

    public static function table(Table $table): Table
    {

        return TableDecorator::make(
            $table
            ->columns([
                //
                Tables\Columns\TextColumn::make('firstname')
                    ->searchable()
                    ->sortable()
                    ->label('Nome'),
                Tables\Columns\TextColumn::make('lastname')
                    ->searchable()
                    ->sortable()
                    ->label('Cognome'),
                Tables\Columns\TextColumn::make('email'),
            ])
            ->filters([
                //
            ])
        );
    }

    public static function getRelations(): array
    {
        return [
            //
        ];
    }

    public static function getPages(): array
    {
        return [
            'index' => Pages\ListAdmins::route('/'),
            'create' => Pages\CreateAdmin::route('/create'),
            'edit' => Pages\EditAdmin::route('/{record}/edit'),
        ];
    }


    protected static function authorizeSuperAdmin(string $permission, User $record): bool
    {
        if ($record->isSuperAdmin()) {
            /** @disregard P1013 */
            return auth()->user()->isSuperAdmin();
        }

        return Auth::user()->can($permission, $record);
    }

    /**
     * As we are not using a dedicated policy,
     * this makes sure that access is denied by default.
     */
    public static function shouldCheckPolicyExistence(): bool
    {
        return false;
    }


    public static function canViewAny(): bool
    {
        return Auth::user()->can('view_any_admin');
    }

    public static function canCreate(): bool
    {
        return Auth::user()->can('create_admin');
    }

    public static function canEdit(Model $record): bool
    {
        // @phpstan-ignore argument.type
        return self::authorizeSuperAdmin('update_admin', $record);
    }

    public static function canDelete(Model $record): bool
    {
        return Auth::user()->can('delete', $record);
    }

    public static function canDeleteAny(): bool
    {
        return Auth::user()->can('deleteAny');
    }

    public static function canForceDelete(Model $record): bool
    {
        return Auth::user()->can('forceDelete', $record);
    }

    public static function canForceDeleteAny(): bool
    {
        return Auth::user()->can('forceDeleteAny');
    }

    public static function canReorder(): bool
    {
        return Auth::user()->can('reorder');
    }

    public static function canReplicate(Model $record): bool
    {
        return Auth::user()->can('replicate', $record);
    }

    public static function canRestore(Model $record): bool
    {
        return Auth::user()->can('restore', $record);
    }

    public static function canRestoreAny(): bool
    {
        return Auth::user()->can('restoreAny');
    }

    public static function canView(Model $record): bool
    {
        // @phpstan-ignore argument.type
        return static::authorizeSuperAdmin('view_admin', $record);

    }


}

