22	/**
23	 * Storico sync per una singola risorsa registrata in SyncRegistry, con action
24	 * di trigger manuale (design doc Parte 2: "Import dati" è UI di dominio, non
25	 * log tecnico).
26	 */
27	class SyncResourceDetail extends Page implements Tables\Contracts\HasTable
28	{
29	    use Tables\Concerns\InteractsWithTable;
30	
31	    protected static ?string $slug = 'sync/{resource}';
32	
33	    protected static bool $shouldRegisterNavigation = false;
34	
35	    public string $resource;
36	
37	    public function mount(string $resource): void
38	    {
39	        if (! SyncRegistry::has($resource)) {
40	            throw new NotFoundHttpException("Risorsa di sync [{$resource}] non registrata.");
41	        }
42	
43	        $this->resource = $resource;
44	    }
45	
46	    public function getTitle(): string | Htmlable
47	    {
48	        return 'Sincronizzazione - ' . SyncRegistry::label($this->resource);
49	    }
50	
51	    public function content(Schema $schema): Schema
52	    {
53	        return $schema->components([
54	            EmbeddedTable::make(),
55	        ]);
56	    }
57	
58	    public function table(Table $table): Table
59	    {
60	        return $table
61	            ->query(fn () => SyncRun::query()->where('resource', $this->resource))
62	            ->defaultSort('started_at', 'desc')
63	            ->poll('5s')
64	            ->columns([
65	                Tables\Columns\TextColumn::make('started_at')
66	                    ->label('Avviato')
67	                    ->dateTime(timezone: 'Europe/Rome')
68	                    ->placeholder('—')
69	                    ->sortable(),
70	                Tables\Columns\TextColumn::make('finished_at')
71	                    ->label('Terminato')
72	                    ->dateTime(timezone: 'Europe/Rome')
73	                    ->placeholder('—'),
74	                Tables\Columns\TextColumn::make('status')
75	                    ->label('Esito')
76	                    ->badge()
77	                    ->formatStateUsing(fn (SyncStatus $state): string => $state->label())
78	                    ->color(fn (SyncStatus $state): string => $state->color()),
79	                Tables\Columns\TextColumn::make('created_count')->label('Creati'),
80	                Tables\Columns\TextColumn::make('updated_count')->label('Aggiornati'),
81	                Tables\Columns\TextColumn::make('deleted_count')->label('Cancellati'),
82	                Tables\Columns\TextColumn::make('failed_count')
83	                    ->label('Falliti')
84	                    ->color(fn (int $state): ?string => $state > 0 ? 'danger' : null),
85	            ])
86	            ->recordActions([
87	                Action::make('errors')
88	                    ->label('Errori')
89	                    ->icon('heroicon-o-exclamation-triangle')
90	                    ->color('danger')
91	                    ->visible(fn (SyncRun $record): bool => filled($record->error) || filled($record->item_errors))
92	                    ->modalHeading('Errori del sync')
93	                    ->modalContent(fn (SyncRun $record) => $this->errorsModalContent($record))
94	                    ->modalSubmitAction(false)
95	                    ->modalCancelActionLabel('Chiudi'),
96	            ])
97	            ->emptyStateHeading('Nessun sync eseguito finora');
98	    }
99	
100	    protected function getHeaderActions(): array
101	    {
102	        return [
103	            Action::make('import')
104	                ->label('Importa dati ora')
105	                ->icon('heroicon-o-arrow-path')
106	                ->disabled(fn (): bool => SyncRun::query()
107	                    ->where('resource', $this->resource)
108	                    ->whereIn('status', [SyncStatus::Pending, SyncStatus::Running])
109	                    ->exists())
110	                ->action(function (): void {
111	                    $run = SyncRun::create([
112	                        'resource' => $this->resource,
113	                        'status' => SyncStatus::Pending,
114	                    ]);
115	
116	                    RunSyncJob::dispatch($run->id);
117	
118	                    Notification::make()
119	                        ->title('Sync avviato')
120	                        ->success()
121	                        ->send();
122	                }),
123	        ];
124	    }
125	
126	    private function errorsModalContent(SyncRun $record): Htmlable
127	    {
128	        $lines = [];
129	
130	        if (filled($record->error)) {
131	            $lines[] = e($record->error);
132	        }
133	
134	        /** @var array<int, array{global_id?: string, message?: string}> $itemErrors */
135	        $itemErrors = $record->item_errors ?? [];
136	
137	        foreach ($itemErrors as $itemError) {
138	            $lines[] = e(($itemError['global_id'] ?? '?') . ': ' . ($itemError['message'] ?? ''));
139	        }
140	
141	        return new HtmlString('<span class="text-sm">' . implode("\n", $lines) . '</span>');
142	    }
143	}
