3	namespace Database\Seeders;
4	
5	use Illuminate\Database\Seeder;
6	use Illuminate\Support\Facades\Artisan;
7	use Spatie\Permission\Models\Permission;
8	use Spatie\Permission\Models\Role;
9	use Spatie\Permission\PermissionRegistrar;
10	
11	class RoleSeeder extends Seeder
12	{
13	    /**
14	     * Ruoli baseline, stesse convenzioni dell'hub (i login però restano
15	     * separati: qui si condivide lo stack, non gli account).
16	     *
17	     * - super_admin: nessun permesso esplicito assegnato, bypassa tutto via
18	     *   Gate::before() registrato nativamente da filament-shield
19	     *   (config `super_admin.define_via_gate`, vedi config/filament-shield.php).
20	     * - Admin: tutti i permessi generati da shield.
21	     * - Editor: view/create/update su tutte le resource, niente delete.
22	     * - Viewer: solo view/view_any su tutte le resource.
23	     *
24	     * `shield:generate` va comunque rilanciato manualmente dopo ogni resource
25	     * nuova — qui serve solo a ripopolare la tabella permissions dopo un
26	     * `migrate:fresh`, che la svuota assieme a tutte le altre.
27	     * `--option=permissions`: solo righe DB, niente riscrittura dei file Policy.
28	     */
29	    public function run(): void
30	    {
31	        Artisan::call('shield:generate', [
32	            '--all' => true,
33	            '--panel' => 'admin',
34	            '--option' => 'permissions',
35	            '--no-interaction' => true,
36	        ]);
37	
38	        app(PermissionRegistrar::class)->forgetCachedPermissions();
39	
40	        Role::firstOrCreate(['name' => 'super_admin', 'guard_name' => 'web']);
41	
42	        $admin = Role::firstOrCreate(['name' => 'Admin', 'guard_name' => 'web']);
43	        $admin->syncPermissions(Permission::where('guard_name', 'web')->get());
44	
45	        $editor = Role::firstOrCreate(['name' => 'Editor', 'guard_name' => 'web']);
46	        $editor->syncPermissions(
47	            Permission::where('guard_name', 'web')
48	                ->where(fn ($query) => $query
49	                    ->where('name', 'like', 'view\_%')
50	                    ->orWhere('name', 'like', 'create\_%')
51	                    ->orWhere('name', 'like', 'update\_%'))
52	                ->get(),
53	        );
54	
55	        $viewer = Role::firstOrCreate(['name' => 'Viewer', 'guard_name' => 'web']);
56	        $viewer->syncPermissions(
57	            Permission::where('guard_name', 'web')
58	                ->where('name', 'like', 'view\_%')
59	                ->get(),
60	        );
61	    }
62	}
